insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-inggris-sma-bacaan_01', 'sub-bahasa-inggris-sma', 'Teks untuk soal nomor 1 s.d. 5!', '<p><strong>Teks untuk soal nomor 1 s.d. 5!</strong></p><p>King Hung Vuong VI had a beautiful daughter. He did not want her to marry just any prince. So, he made an announcement that he was looking for the right husband for her. Many princes came from faraway lands, but none of them was a good match for the princess.</p><p>Son Tinh was the Spirit of the Mountain, and Thuy Tinh was the Spirit of the Waters. One day, they both appeared as young noblemen and asked to marry the princess. They were equally talented, powerful, and respected. The King found it hard to choose, so he decided to give them a test. He said that the one who brought the proper wedding gifts first the next morning would marry his daughter.</p><p>The next day, Son Tinh arrived early with his gifts. The King kept his promise and gave the princess to him. Thuy Tinh was angry about losing. He challenged Son Tinh to fight for the princess. But Son Tinh refused, believing he had already won fairly. Furious, Thuy Tinh used his power to call the rivers and streams to rise. Soon, the land was covered with floods that destroyed crops and homes.</p><p>Son Tinh stayed calm in his mountain palace. Whenever the water rose, he made his mountains higher. After many days of fighting, Thuy Tinh grew tired and ordered the waters to retreat. Still, he never accepted his defeat. Every year, he tried again to attack, and this is how monsoons came to Vietnam.</p>', 0) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
insert into public.passages (id, subject_id, label, body_html, sort_order) values ('psg-tka-bahasa-inggris-sma-bacaan_02', 'sub-bahasa-inggris-sma', 'Teks untuk soal nomor 6 s.d. 10!', '<p><strong>Teks untuk soal nomor 6 s.d. 10!</strong></p><p><strong><img src="/soal/04907_553dcd423e6da03fc4942ea98fcb90d4.png" alt=""/></strong></p>', 1) on conflict (id) do update set subject_id = excluded.subject_id, label = excluded.label, body_html = excluded.body_html, sort_order = excluded.sort_order;
